//! Volume ids and class parameters against fixtures generated by the
//! originating project's code (tests/fixtures/README.md).

mod common;
use common::*;

#[test]
fn class_parameters_parse_identically() {
    let want = std::fs::read_to_string(fixtures().join("class_params.tsv")).unwrap();
    let got: Vec<String> = class_cases()
        .iter()
        .enumerate()
        .map(|(i, c)| class_line(i, c))
        .collect();
    assert_eq!(want.trim_end().split('\n').collect::<Vec<_>>(), got);
}

#[test]
fn volume_ids_encode_decode_identically() {
    let text = std::fs::read_to_string(fixtures().join("volume_ids.tsv")).unwrap();
    let mut n = 0;
    for line in text.lines() {
        check_id_line(line);
        n += 1;
    }
    assert!(n >= 10, "{n}");
}

/// The same parameters under another default prefix change the prefix and
/// nothing else, so an application's data location is its own choice.
#[test]
fn the_default_prefix_is_the_callers() {
    use replicix_csi_common::params::ClassParams;
    let c = &class_cases()[0];
    let a = ClassParams::parse(c, &default_prefix()).unwrap();
    let b = ClassParams::parse(c, "other-csi").unwrap();
    assert_eq!(b.prefix, "other-csi");
    assert_eq!(
        ClassParams {
            prefix: a.prefix.clone(),
            ..b
        },
        a
    );
}
